//! English (American and British) grapheme-to-phoneme, dictionary-first.
//!
//! Unlike the other Kokoro languages, English is not phonemic enough for
//! rules alone: two words spelled alike can sound completely different
//! (`read` past vs. present tense, `wind` the noun vs. the verb), and vowel
//! reduction in unstressed syllables is largely lexical, not rule-governed.
//! So this looks words up in misaki's own pronunciation dictionaries
//! (`en_us.tsv`/`en_gb.tsv`, generated by `tools/gen_en_data.py` - see
//! `NOTICE`) first, and only falls back to a hand-written letter-to-sound
//! approximation ([`fallback::approximate`]) for words the dictionary has
//! never heard of.
//!
//! Full part-of-speech tagging is out of scope (misaki resolves homographs
//! with spaCy tags; a from-scratch tagger is not something this crate
//! carries), but one large, high-confidence slice of English's homographs
//! is handled anyway: the productive noun-front-stress/verb-back-stress
//! pattern ("RECord" the noun vs. "reCORD" the verb, "OBject" vs. "obJECT",
//! "PRESent" vs. "preSENT", ...), which covers 240+ common words per
//! `tools/gen_en_data.py`'s extraction of misaki's own VERB-tagged
//! alternates into `en_us_verb.tsv`/`en_gb_verb.tsv`. [`VERB_CONTEXT`]
//! checks the word (or two) *preceding* the homograph for an unambiguous
//! verb-context signal (an infinitive "to", or a modal: "will record", "to
//! object", "can present") and reaches for the verb-tagged pronunciation
//! only then - an unmarked occurrence ("the record", "I record") still
//! defaults to the (usually noun/adjective) `DEFAULT` reading, same as
//! before this existed. A single adverb is allowed to sit between the
//! trigger and the homograph ("will surely record", "to quietly object"),
//! since an adverb is the only word class that can legally occupy that slot
//! in English; [`looks_like_adverb`] recognizes one by its `-ly` suffix.
//! Not covered: homographs distinguished by *tense* rather than word class
//! ("read"/"lead" past vs. present, spelled identically either way) - no
//! signal this simple can tell those apart; nor does a verb-context signal
//! carry forward past that one intervening word, so "record the meeting and
//! present the results" still defaults "present" to its noun reading.
//!
//! Numbers, not covered by the dictionary at all, are expanded to words
//! first ([`numbers::expand`]) and then looked up like any other word - so
//! "24" and "twenty-four" take the same path and get the same phonemes.

mod fallback;
mod numbers;

use super::{text, Lang};
use std::collections::HashMap;
use std::sync::OnceLock;

const EN_US_TSV: &str = include_str!("en_us.tsv");
const EN_GB_TSV: &str = include_str!("en_gb.tsv");
const EN_US_VERB_TSV: &str = include_str!("en_us_verb.tsv");
const EN_GB_VERB_TSV: &str = include_str!("en_gb_verb.tsv");

/// Words that unambiguously introduce a bare-infinitive verb form: an
/// infinitive marker, or a modal. "will record", "to object", "can present"
/// - checked against the word *before* a potential homograph to decide
/// whether to reach for its VERB-tagged pronunciation instead of DEFAULT.
const VERB_CONTEXT: &[&str] = &[
    "to", "will", "would", "can", "could", "shall", "should", "must", "might", "may", "let",
    "let's",
];

/// A crude but low-risk adverb detector for the one slot where it matters:
/// between a [`VERB_CONTEXT`] trigger and the homograph it governs ("will
/// *surely* record"). The `-ly` suffix false-positives on a handful of
/// non-adverbs (e.g. "family"), but those cannot occur in this exact
/// syntactic slot in practice, so the simple check is safe here.
fn looks_like_adverb(word: &str) -> bool {
    let lower = word.to_lowercase();
    lower.len() > 2 && lower.ends_with("ly")
}

struct Lexicon {
    words: HashMap<String, &'static str>,
}

/// Python's `str.capitalize()`: first character upper, the rest lower.
fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        None => String::new(),
        Some(first) => {
            first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase()
        }
    }
}

impl Lexicon {
    /// Port of misaki's `Lexicon.grow_dictionary`: a lowercase entry also
    /// answers to its capitalized form and vice versa, but an exact match in
    /// the source dictionary always wins over a generated variant.
    fn load(tsv: &'static str) -> Self {
        let mut words = HashMap::with_capacity(tsv.lines().count() * 2);
        let entries: Vec<(&str, &str)> = tsv
            .lines()
            .filter_map(|line| line.split_once('\t'))
            .collect();
        for &(w, p) in &entries {
            if w.chars().count() < 2 {
                continue;
            }
            let lower = w.to_lowercase();
            if w == lower {
                let cap = capitalize(w);
                if cap != w {
                    words.entry(cap).or_insert(p);
                }
            } else if *w == capitalize(&lower) {
                words.entry(lower).or_insert(p);
            }
        }
        for (w, p) in entries {
            words.insert(w.to_string(), p);
        }
        Lexicon { words }
    }

    fn get(&self, word: &str) -> Option<&'static str> {
        self.words.get(word).copied()
    }

    /// Port of `Lexicon.is_known`, minus the NNP/tag-dependent branches that
    /// need a part-of-speech tagger this crate does not have.
    fn is_known(&self, word: &str) -> bool {
        if self.words.contains_key(word) {
            return true;
        }
        if word.chars().count() == 1 {
            return true;
        }
        let upper = word.to_uppercase();
        if word == upper && self.words.contains_key(&word.to_lowercase()) {
            return true;
        }
        false
    }
}

fn us_lexicon() -> &'static Lexicon {
    static LEX: OnceLock<Lexicon> = OnceLock::new();
    LEX.get_or_init(|| Lexicon::load(EN_US_TSV))
}

fn gb_lexicon() -> &'static Lexicon {
    static LEX: OnceLock<Lexicon> = OnceLock::new();
    LEX.get_or_init(|| Lexicon::load(EN_GB_TSV))
}

fn load_verb_table(tsv: &'static str) -> HashMap<&'static str, &'static str> {
    tsv.lines().filter_map(|line| line.split_once('\t')).collect()
}

fn us_verb_table() -> &'static HashMap<&'static str, &'static str> {
    static TABLE: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    TABLE.get_or_init(|| load_verb_table(EN_US_VERB_TSV))
}

fn gb_verb_table() -> &'static HashMap<&'static str, &'static str> {
    static TABLE: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    TABLE.get_or_init(|| load_verb_table(EN_GB_VERB_TSV))
}

/// Port of misaki's `_s`/`_ed`/`_ing`: how a stem's final phoneme decides the
/// suffix's own pronunciation. <https://en.wiktionary.org/wiki/-s> etc.
mod suffix {
    pub(super) fn s(stem: &str, british: bool) -> String {
        match stem.chars().last() {
            Some(c) if "ptkfθ".contains(c) => format!("{stem}s"),
            Some(c) if "szʃʒʧʤ".contains(c) => {
                format!("{stem}{}z", if british { "ɪ" } else { "ᵻ" })
            }
            _ => format!("{stem}z"),
        }
    }

    pub(super) fn ed(stem: &str, british: bool) -> String {
        let mut chars = stem.chars();
        let last = match chars.next_back() {
            Some(c) => c,
            None => return stem.to_string(),
        };
        if "pkfθʃsʧ".contains(last) {
            format!("{stem}t")
        } else if last == 'd' {
            format!("{stem}{}d", if british { "ɪ" } else { "ᵻ" })
        } else if last != 't' {
            format!("{stem}d")
        } else if british || stem.chars().count() < 2 {
            format!("{stem}ɪd")
        } else {
            let second_last = chars.next_back();
            let taus = "AIOWYiuæɑəɛɪɹʊʌ";
            if second_last.is_some_and(|c| taus.contains(c)) {
                let base: String = stem.chars().take(stem.chars().count() - 1).collect();
                format!("{base}ɾᵻd")
            } else {
                format!("{stem}ᵻd")
            }
        }
    }

    pub(super) fn ing(stem: &str, british: bool) -> Option<String> {
        let mut chars: Vec<char> = stem.chars().collect();
        let last = *chars.last()?;
        if british {
            if "əː".contains(last) {
                return None;
            }
        } else if chars.len() > 1 && last == 't' {
            let taus = "AIOWYiuæɑəɛɪɹʊʌ";
            if taus.contains(chars[chars.len() - 2]) {
                chars.pop();
                let base: String = chars.into_iter().collect();
                return Some(format!("{base}ɾɪŋ"));
            }
        }
        Some(format!("{stem}ɪŋ"))
    }
}

/// Try to derive `word`'s phonemes from a known stem plus `-s`/`-ed`/`-ing`,
/// the way misaki's `stem_s`/`stem_ed`/`stem_ing` do.
fn lookup_by_stemming(lex: &Lexicon, word: &str, british: bool) -> Option<String> {
    let lower = word.to_lowercase();
    let chars: Vec<char> = lower.chars().collect();
    let n = chars.len();

    if n >= 3 && lower.ends_with('s') {
        let stem_opt = if !lower.ends_with("ss") && lex.is_known(&lower[..n - 1]) {
            Some(lower[..n - 1].to_string())
        } else if (lower.ends_with("'s")
            || (n > 4 && lower.ends_with("es") && !lower.ends_with("ies")))
            && lex.is_known(&lower[..n - 2])
        {
            Some(lower[..n - 2].to_string())
        } else if n > 4 && lower.ends_with("ies") && lex.is_known(&format!("{}y", &lower[..n - 3]))
        {
            Some(format!("{}y", &lower[..n - 3]))
        } else {
            None
        };
        if let Some(stem) = stem_opt {
            if let Some(ps) = lookup_word(lex, &stem, british) {
                return Some(suffix::s(&ps, british));
            }
        }
    }

    if n >= 4 && lower.ends_with('d') {
        let stem_opt = if !lower.ends_with("dd") && lex.is_known(&lower[..n - 1]) {
            Some(lower[..n - 1].to_string())
        } else if n > 4 && lower.ends_with("ed") && !lower.ends_with("eed") && lex.is_known(&lower[..n - 2]) {
            Some(lower[..n - 2].to_string())
        } else {
            None
        };
        if let Some(stem) = stem_opt {
            if let Some(ps) = lookup_word(lex, &stem, british) {
                return Some(suffix::ed(&ps, british));
            }
        }
    }

    if n >= 5 && lower.ends_with("ing") {
        let stem_opt = if n > 5 && lex.is_known(&lower[..n - 3]) {
            Some(lower[..n - 3].to_string())
        } else if lex.is_known(&format!("{}e", &lower[..n - 3])) {
            Some(format!("{}e", &lower[..n - 3]))
        } else if n > 5 && doubled_consonant_before_ing(&lower) && lex.is_known(&lower[..n - 4]) {
            Some(lower[..n - 4].to_string())
        } else {
            None
        };
        if let Some(stem) = stem_opt {
            if let Some(ps) = lookup_word(lex, &stem, british) {
                return suffix::ing(&ps, british);
            }
        }
    }

    None
}

/// `([bcdgklmnprstvxz])\1ing$|cking$` from misaki, without pulling in `regex`.
fn doubled_consonant_before_ing(word: &str) -> bool {
    if let Some(rest) = word.strip_suffix("cking") {
        if rest.chars().next_back().is_some() {
            return true;
        }
    }
    let chars: Vec<char> = word.chars().collect();
    let n = chars.len();
    if n < 5 || &chars[n - 3..] != ['i', 'n', 'g'] {
        return false;
    }
    let (a, b) = (chars[n - 5], chars[n - 4]);
    a == b && "bcdgklmnprstvxz".contains(a)
}

/// A handful of very high-frequency function words whose natural pronunciation
/// depends on context (mainly whether the next word starts with a vowel
/// sound) rather than being fixed, the way misaki's `get_special_case`
/// handles them. Approximated here with a look at the next word's spelling,
/// since there is no phonemizer-independent way to know its sound without
/// phonemizing it first.
fn special_case(word: &str, next_word: Option<&str>) -> Option<&'static str> {
    let next_starts_with_vowel = next_word
        .and_then(|w| w.chars().find(|c| c.is_alphabetic()))
        .is_some_and(|c| "aeiouAEIOU".contains(c));
    match word {
        "a" | "A" => Some("ɐ"),
        "an" | "An" | "AN" => Some("ɐn"),
        "am" | "Am" | "AM" => Some(if next_word.is_some() { "ɐm" } else { "æm" }),
        "the" | "The" | "THE" => Some(if next_starts_with_vowel { "ði" } else { "ðə" }),
        "to" | "To" => Some(if next_word.is_none() {
            "tu"
        } else if next_starts_with_vowel {
            "tʊ"
        } else {
            "tə"
        }),
        "I" => Some("\u{2cc}I"), // secondary stress, as misaki's PRP case
        _ => None,
    }
}

/// Look up one already-tokenized word (no whitespace, no clause punctuation).
fn lookup_word(lex: &Lexicon, word: &str, british: bool) -> Option<String> {
    if let Some(ps) = lex.get(word) {
        return Some(ps.to_string());
    }
    lookup_by_stemming(lex, word, british)
}

/// Whether `token` is a number this module's [`numbers`] submodule can
/// expand: digits, optionally with `,`/`.` separators and a few affixes.
fn looks_numeric(token: &str) -> bool {
    let core = token.trim_start_matches(['$', '£', '€', '-']);
    let core = core
        .strip_suffix("st")
        .or_else(|| core.strip_suffix("nd"))
        .or_else(|| core.strip_suffix("rd"))
        .or_else(|| core.strip_suffix("th"))
        .unwrap_or(core);
    !core.is_empty() && core.chars().next().is_some_and(|c| c.is_ascii_digit())
}

fn phonemize_word(
    lex: &Lexicon,
    word: &str,
    prev_prev_word: Option<&str>,
    prev_word: Option<&str>,
    next_word: Option<&str>,
    british: bool,
) -> Option<String> {
    if let Some(ps) = special_case(word, next_word) {
        return Some(ps.to_string());
    }
    if looks_numeric(word) {
        let expanded = numbers::expand(word)?;
        let mut out = Vec::new();
        let words: Vec<&str> = expanded.split_whitespace().collect();
        for (i, w) in words.iter().enumerate() {
            let next = words.get(i + 1).copied().or(next_word);
            out.push(phonemize_word(lex, w, None, None, next, british)?);
        }
        return Some(out.join(" "));
    }
    // The noun-front-stress/verb-back-stress homograph class ("record",
    // "object", "present", ...): only reached for after an unambiguous
    // verb-context word - directly before it, or one adverb removed ("will
    // surely record") - so an unmarked occurrence is unaffected. See the
    // module doc and `VERB_CONTEXT`.
    let verb_context_active = prev_word.is_some_and(|p| VERB_CONTEXT.contains(&p.to_lowercase().as_str()))
        || (prev_word.is_some_and(|p| looks_like_adverb(p))
            && prev_prev_word.is_some_and(|p| VERB_CONTEXT.contains(&p.to_lowercase().as_str())));
    if verb_context_active {
        let verb_table = if british { gb_verb_table() } else { us_verb_table() };
        if let Some(&ps) = verb_table.get(word.to_lowercase().as_str()) {
            return Some(ps.to_string());
        }
    }
    if let Some(ps) = lookup_word(lex, word, british) {
        return Some(ps);
    }
    Some(fallback::approximate(word))
}

pub(crate) fn phonemize(text_in: &str, lang: Lang) -> Result<String, String> {
    let british = lang == Lang::BritishEnglish;
    let lex = if british { gb_lexicon() } else { us_lexicon() };
    text::phonemize_clauses(text_in, |run| {
        let words: Vec<&str> = run.split_whitespace().collect();
        let mut out = Vec::with_capacity(words.len());
        for (i, &w) in words.iter().enumerate() {
            let prev_prev = i.checked_sub(2).and_then(|j| words.get(j)).copied();
            let prev = i.checked_sub(1).and_then(|j| words.get(j)).copied();
            let next = words.get(i + 1).copied();
            let ps = phonemize_word(lex, w, prev_prev, prev, next, british).unwrap_or_default();
            if !ps.is_empty() {
                out.push(ps);
            }
        }
        Ok(out.join(" "))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn common_words_come_straight_from_the_dictionary() {
        let lex = us_lexicon();
        assert_eq!(lex.get("cat"), Some("kˈæt"));
    }

    #[test]
    fn grown_dictionary_answers_to_the_other_case() {
        let lex = us_lexicon();
        // "cat" is lowercase in the source dictionary; "Cat" must resolve too.
        assert!(lex.get("Cat").is_some());
    }

    #[test]
    fn plural_of_a_known_singular_is_derived() {
        let lex = us_lexicon();
        assert!(
            lex.get("aardvarks").is_none(),
            "not itself in the dictionary"
        );
        let ps = lookup_by_stemming(lex, "aardvarks", false).expect("stems to aardvark + s");
        assert!(ps.ends_with('s'), "voiceless stem takes /s/: {ps}");
    }

    #[test]
    fn past_tense_of_a_known_verb_is_derived() {
        let lex = us_lexicon();
        let ps = lookup_by_stemming(lex, "walked", false).expect("stems to walk + ed");
        assert!(ps.ends_with('t'), "voiceless stem takes /t/: {ps}");
    }

    #[test]
    fn the_reduces_before_a_consonant_and_lengthens_before_a_vowel() {
        assert_eq!(special_case("the", Some("cat")), Some("ðə"));
        assert_eq!(special_case("the", Some("apple")), Some("ði"));
    }

    #[test]
    fn phonemizing_a_sentence_preserves_punctuation() {
        let ps = phonemize("Hello, world!", Lang::AmericanEnglish).unwrap();
        assert!(ps.contains(','));
        assert!(ps.contains('!'));
    }

    #[test]
    fn numbers_are_spelled_out_and_looked_up() {
        let ps = phonemize("I have 24 cats.", Lang::AmericanEnglish).unwrap();
        // "twenty" + "four", both real dictionary words.
        let twenty = us_lexicon().get("twenty").unwrap();
        let four = us_lexicon().get("four").unwrap();
        assert!(ps.contains(twenty), "{ps} missing {twenty}");
        assert!(ps.contains(four), "{ps} missing {four}");
    }

    #[test]
    fn verb_context_picks_the_verb_tagged_homograph() {
        // "record" is a classic noun/verb stress-shift homograph: DEFAULT
        // (noun) is front-stressed, the VERB tag back-stressed. An
        // unambiguous verb-context word before it ("will"/"to"/...)
        // should select the verb reading; an ordinary determiner should
        // not.
        let noun = phonemize_word(us_lexicon(), "record", None, None, None, false).unwrap();
        let verb_after_will =
            phonemize_word(us_lexicon(), "record", None, Some("will"), None, false).unwrap();
        let verb_after_to =
            phonemize_word(us_lexicon(), "record", None, Some("to"), None, false).unwrap();
        let still_noun_after_the =
            phonemize_word(us_lexicon(), "record", None, Some("the"), None, false).unwrap();
        assert_ne!(noun, verb_after_will, "\"will\" should trigger the verb reading");
        assert_eq!(verb_after_will, verb_after_to);
        assert_eq!(noun, still_noun_after_the, "\"the\" must not trigger it");
    }

    #[test]
    fn verb_context_survives_one_intervening_adverb() {
        // "will surely record": the adverb "surely" sits between the modal
        // and the homograph, same as it would in real speech - the verb
        // reading should still win.
        let noun = phonemize_word(us_lexicon(), "record", None, None, None, false).unwrap();
        let verb_after_adverb =
            phonemize_word(us_lexicon(), "record", Some("will"), Some("surely"), None, false)
                .unwrap();
        assert_ne!(noun, verb_after_adverb, "an intervening adverb should not block the verb reading");

        // But an intervening word that is not an adverb ("will the record")
        // must not trigger it - "the" is not "-ly", and the sentence isn't
        // even grammatical with a verb reading there.
        let still_noun =
            phonemize_word(us_lexicon(), "record", Some("will"), Some("the"), None, false).unwrap();
        assert_eq!(noun, still_noun, "a non-adverb in that slot must not trigger the verb reading");
    }

    #[test]
    fn verb_context_contraction_lets_is_recognized() {
        let ps = phonemize("let's close the door", Lang::AmericanEnglish).unwrap();
        let verb_close = us_verb_table().get("close").unwrap();
        assert!(ps.contains(verb_close), "{ps}: \"let's\" should trigger the verb reading");
    }

    #[test]
    fn verb_context_does_not_affect_unrelated_words() {
        // Sanity: the heuristic only ever changes words that actually have
        // a verb-tagged alternate; an ordinary word after "will"/"to" is
        // untouched.
        let after_will = phonemize_word(us_lexicon(), "cat", None, Some("will"), None, false);
        let plain = phonemize_word(us_lexicon(), "cat", None, None, None, false);
        assert_eq!(after_will, plain);
    }

    #[test]
    fn unknown_words_fall_back_rather_than_disappear() {
        let ps = phonemize("Zzyzxville", Lang::AmericanEnglish).unwrap();
        assert!(!ps.is_empty());
    }
}
